"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["65547"],{47764(e){e.exports=JSON.parse('{"id":"FIN-1101","slug":"capital-intensity","term":"Capital Intensity","also_known_as":[],"difficulty":"Advanced","definition":"Capital intensity is the amount of capital, such as property, equipment and other assets, a business needs to generate each unit of revenue.","explanation":["Capital intensity is often measured as total assets divided by revenue, or sometimes as capital expenditure divided by revenue. A higher figure means the business needs more assets to produce its sales.","For example, a company with total assets of 8,000,000 and revenue of 4,000,000 has a capital intensity of 2. It needs 2 of assets for each 1 of annual revenue.","Capital-intensive industries include utilities, telecoms, airlines, steel, oil and gas and semiconductor manufacturing. Less capital-intensive businesses include software, consulting and many online services.","Capital intensity affects risk and returns. Capital-intensive businesses usually have high fixed costs and high operating leverage, so profits are sensitive to demand. They need large ongoing investment to maintain and grow, which reduces free cash flow. However, high capital needs also create barriers to entry, protecting established companies from new competitors."],"note":"","total":1500,"prev":{"slug":"capital-gains-tax","term":"Capital Gains Tax"},"next":{"slug":"capital-loss","term":"Capital Loss"}}')}}]);